// Versioned JSON records. SETUP: paste the data table id below (n8n → Data tables → the table's URL).
const TABLE_ID = 'REPLACE_WITH_RECORDS_TABLE_ID';
const first = $input.first().json;
const body = first.body || first;
const request_id = (typeof body.request_id === 'string' && body.request_id.length <= 100) ? body.request_id : undefined;
const fail = (code, message, status_code = 400) => [{ json: { valid: false, status_code, error: { code, message }, request_id } }];
const isIso = (v) => typeof v === 'string' && v.trim() !== '' && !isNaN(new Date(v).getTime());
if (TABLE_ID.startsWith('REPLACE')) return fail('SETUP_ERROR', 'records data table id is not set in Validate Input', 500);
const base = 'http://localhost:5678/api/v1/data-tables/' + TABLE_ID + '/rows';
const op = body.op;
if (!['get', 'put', 'history', 'list'].includes(op)) return fail('VALIDATION_ERROR', 'op must be get, put, history or list');
const KEY = /^[A-Za-z0-9][A-Za-z0-9:_\-./]{0,199}$/;
let filter, limit;
if (op === 'list') {
  if (typeof body.prefix !== 'string' || !KEY.test(body.prefix)) return fail('VALIDATION_ERROR', 'prefix is required (letters, digits, : _ - . /)');
  filter = { type: 'and', filters: [{ columnName: 'key', condition: 'like', value: body.prefix + '%' }] };
  limit = 250;
} else {
  if (typeof body.key !== 'string' || !KEY.test(body.key)) return fail('VALIDATION_ERROR', 'key is required (letters, digits, : _ - . /)');
  filter = { type: 'and', filters: [{ columnName: 'key', condition: 'eq', value: body.key }] };
  limit = op === 'history' ? Math.max(1, Math.min(50, parseInt(body.limit ?? 20, 10) || 20)) : 1;
}
let value, expectedVersion = null, savedBy = 'josh';
if (op === 'put') {
  if (body.value === undefined) return fail('VALIDATION_ERROR', 'value is required');
  value = body.value;
  if (JSON.stringify(value).length > 200000) return fail('VALIDATION_ERROR', 'value is larger than 200 KB');
  if (body.expectedVersion != null) {
    expectedVersion = parseInt(body.expectedVersion, 10);
    if (isNaN(expectedVersion) || expectedVersion < 0) return fail('VALIDATION_ERROR', 'expectedVersion must be a whole number');
  }
  if (body.savedBy != null) {
    if (!['josh', 'joce', 'ea', 'dev'].includes(body.savedBy)) return fail('VALIDATION_ERROR', 'savedBy must be josh, joce, ea or dev');
    savedBy = body.savedBy;
  }
}
const url = base + '?limit=' + limit + '&sortBy=' + encodeURIComponent(op === 'list' ? 'key:asc' : 'version:desc') + '&filter=' + encodeURIComponent(JSON.stringify(filter));
return [{ json: { valid: true, op, request_id, key: body.key, prefix: body.prefix, value, expectedVersion, savedBy, insertUrl: base, req: { url } } }];

const v = $('Validate Input').first().json;
const r = $input.first().json || {};
const err = (code, message, status_code) => [{ json: { ok: false, write: false, status_code, request_id: v.request_id, error: { code, message } } }];
if (!(r.statusCode >= 200 && r.statusCode < 300)) return err('UPSTREAM_ERROR', 'data table answered ' + r.statusCode + ': ' + JSON.stringify(r.body || '').slice(0, 300), 502);
const rows = (r.body && Array.isArray(r.body.data)) ? r.body.data : [];
const parse = (s) => { try { return JSON.parse(s); } catch (e) { return null; } };
const toRec = (row) => ({ key: row.key, version: Number(row.version), value: parse(row.value_json), savedAt: row.saved_at || null, savedBy: row.saved_by || null });
const ok = (data) => [{ json: { ok: true, write: false, response: { ok: true, request_id: v.request_id, data } } }];

if (v.op === 'get') return ok(rows[0] ? toRec(rows[0]) : { key: v.key, version: 0, value: null, savedAt: null, savedBy: null });
if (v.op === 'history') return ok({ key: v.key, versions: rows.map(toRec) });
if (v.op === 'list') {
  const latest = {};
  for (const row of rows) { const rec = toRec(row); if (!latest[rec.key] || rec.version > latest[rec.key].version) latest[rec.key] = rec; }
  return ok({ prefix: v.prefix, items: Object.values(latest), truncated: rows.length >= 250 || !!(r.body && r.body.nextCursor) });
}
// put: append version N+1 (never overwrite)
const current = rows[0] ? Number(rows[0].version) : 0;
if (v.expectedVersion !== null && v.expectedVersion !== current) {
  return err('CONFLICT', 'record changed since it was loaded (now version ' + current + ')', 409);
}
const savedAt = new Date().toISOString();
const row = { key: v.key, version: current + 1, value_json: JSON.stringify(v.value), saved_at: savedAt, saved_by: v.savedBy };
return [{ json: { ok: true, write: true, insertUrl: v.insertUrl, row,
  response: { ok: true, request_id: v.request_id, data: { key: v.key, version: current + 1, value: v.value, savedAt, savedBy: v.savedBy } } } }];

// The write only counts if the data table said so.
const d = $('Decide').first().json;
const r = $input.first().json || {};
if (r.statusCode >= 200 && r.statusCode < 300) return [{ json: { ok: true, response: d.response } }];
return [{ json: { ok: false, status_code: 502, request_id: d.response && d.response.request_id, error: { code: 'UPSTREAM_ERROR', message: 'data table write answered ' + r.statusCode + ': ' + JSON.stringify(r.body || '').slice(0, 300) } } }];
